#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define INF INT64_MAX

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *T = malloc((size_t)N * sizeof(int));
    for (int i = 0; i < N; ++i) scanf("%d", &T[i]);
    qsort(T, N, sizeof(int), compare_ints);

    int M = N - K;
    int64_t *prev2 = malloc((size_t)(K + 1) * sizeof(int64_t));
    int64_t *prev1 = malloc((size_t)(K + 1) * sizeof(int64_t));
    int64_t *cur = malloc((size_t)(K + 1) * sizeof(int64_t));

    for (int j = 0; j <= K; ++j) prev1[j] = INF;
    prev1[0] = 0;

    for (int i = 1; i <= M; ++i) {
        for (int j = 0; j <= K; ++j) cur[j] = prev1[j];

        if (i >= 2) {
            int64_t diff = (int64_t)T[i - 1] - T[i - 2];
            int64_t cost = diff * diff;

            for (int j = 1; j <= K; ++j) {
                if (prev2[j - 1] != INF) {
                    int64_t candidate = prev2[j - 1] + cost;
                    if (candidate < cur[j]) cur[j] = candidate;
                }
            }
        }

        int64_t *tmp = prev2;
        prev2 = prev1;
        prev1 = cur;
        cur = tmp;
    }

    printf("%lld\n", (long long)prev1[K]);

    free(T);
    free(prev2);
    free(prev1);
    free(cur);
    return 0;
}
