#define MAX_N 10000
#define MAX_K 3000
#define INF INT64_MAX

static int dolls[MAX_N];
static int64_t dp[3][MAX_K + 1];

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    for (int i = 0; i < N; i++) scanf("%d", &dolls[i]);
    qsort(dolls, N, sizeof(int), compare_ints);

    for (int r = 0; r < 3; r++)
        for (int j = 0; j <= K; j++)
            dp[r][j] = INF;
    dp[0][0] = 0;

    for (int i = 1; i <= N; i++) {
        int cur = i % 3;
        int prev = (i - 1) % 3;
        int prev2 = (i + 1) % 3;

        for (int j = 0; j <= K; j++)
            dp[cur][j] = dp[prev][j];

        if (i >= 2) {
            int max_j = i / 2;
            if (max_j > K) max_j = K;

            int64_t diff = (int64_t)dolls[i - 1] - dolls[i - 2];
            int64_t cost = diff * diff;

            for (int j = 1; j <= max_j; j++) {
                int bound = N - 3 * K + 3 * j - 1;
                if (i <= bound && dp[prev2][j - 1] != INF) {
                    int64_t candidate = dp[prev2][j - 1] + cost;
                    if (candidate < dp[cur][j])
                        dp[cur][j] = candidate;
                }
            }
        }
    }

    printf("%lld\n", (long long)dp[N % 3][K]);
    return 0;
}
